import React, { useState, useEffect } from 'react';
import { getFranchises } from '../services/api';

const User = () => {
  const [examDataList, setExamDataList] = useState([]);

  useEffect(() => {
    const fetchExamData = async () => {
      try {
        const response = await getFranchises();

        // Assuming userFranchiseId is the ID of the franchise associated with the logged-in user
        const userFranchiseId = getUserFranchiseId(); // Replace with actual logic to get user franchise ID
        const userFranchise = response.data.find((franchise) => franchise._id === userFranchiseId);

        if (userFranchise) {
          setExamDataList(userFranchise.examData || []);
        } else {
          setExamDataList([]);
        }
      } catch (error) {
        console.error('Error fetching exam data:', error);
        alert('Failed to fetch exam data');
      }
    };

    fetchExamData();
  }, []);

  // Placeholder function to get the franchise ID of the logged-in user
  const getUserFranchiseId = () => {
    // Replace with actual implementation to retrieve user franchise ID
    return "user-franchise-id"; // Example ID
  };

  return (
    <div>
      <h1>Exam Data</h1>

      {/* Table to display exam data */}
      {examDataList.length > 0 ? (
        <table border="1">
          <thead>
            <tr>
              <th>Exam Name</th>
              <th>Date</th>
              <th>Students Attended</th>
            </tr>
          </thead>
          <tbody>
            {examDataList.map((exam, index) => (
              <tr key={index}>
                <td>{exam.examName}</td>
                <td>{exam.date}</td>
                <td>{exam.studentsAttended}</td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <p>No exam data available for your franchise.</p>
      )}
    </div>
  );
};

export default User;
